/* Science Quest: GL-style practice tests (original questions, written in the style of the GL Progress Test in Science).
   Each question:  d = B (biology) / C (chemistry) / P (physics)
                   s = K (knowledge and understanding) / A (applying knowledge) / W (working scientifically)
                   t = 'mc' (default: one answer, the FIRST option is correct)
                       'two' (tick two: the FIRST TWO options are correct)
                       'order' (put in order: options are listed in the CORRECT order)
                   v = picture (same codes as Science Practice), tb = a table [[headings],[row],[row]] */
window.SQ_GL = window.SQ_GL || {};

window.SQ_GL.g2 = {name:'Grade 2', year:'Year 3', level:'Level 8', mins:45, intro:'Plants, animals and humans, rocks and soils, light, and forces and magnets.',
qs:[
 {d:'B',s:'K',v:'plant:roots',q:'Look at the part of the plant the arrow is pointing to. What is its job?',o:['To take in water and hold the plant in the soil','To make seeds for new plants','To attract bees and other insects'],why:'Roots grow down into the soil. They take in water and nutrients and hold the plant steady.'},
 {d:'B',s:'K',q:'Which part of a flowering plant makes the seeds?',o:['The flower','The roots','The stem'],why:'After a flower is pollinated, seeds form inside it, often inside a fruit.'},
 {d:'B',s:'A',v:'celery:#3D8BE0',q:'Ella stood a white flower in a glass of blue water. The next day, the petals had blue lines in them. What does this show?',o:['Water is transported up the stem to the flower','The flower is making blue paint','The petals soaked up blue light'],why:'Water is transported up through tiny tubes in the stem to the leaves and flowers. The blue colour travelled with it.'},
 {d:'B',s:'W',tb:[['Plant','Where it was kept','Height after 2 weeks'],['A','Sunny windowsill','12 cm'],['B','Shady corner','8 cm'],['C','Dark cupboard','3 cm (pale and thin)']],q:'Class 2 grew three bean plants in different places. Which conclusion do the results support?',o:['The more light a plant had, the taller and healthier it grew','The plants in the dark grew the tallest','Light makes no difference to how plants grow'],why:'Plant A had the most light and grew tallest. Plant C had no light and grew pale and thin. Plants need light to grow well.'},
 {d:'B',s:'W',tb:[['Plant','Where it was kept','Height after 2 weeks'],['A','Sunny windowsill','12 cm'],['B','Shady corner','8 cm'],['C','Dark cupboard','3 cm (pale and thin)']],q:'To make this a fair test, which variable should the class keep the same for all three plants?',o:['The amount of water each plant is given','The amount of light each plant gets','Where each plant is kept'],why:'In a fair test you only change one thing (here, the light). Everything else, like the water and the type of seed, stays the same.'},
 {d:'B',s:'K',t:'two',q:'Which TWO things does a plant need for life and growth?',o:['Light','Water','Salt','Darkness'],why:'Plants need light, water, air, nutrients from the soil and room to grow.'},
 {d:'B',s:'K',t:'order',q:'Put the stages of the life cycle of a flowering plant in the correct order. Start with the seed.',o:['A seed is planted','A small seedling grows','The plant grows flowers','The flowers make new seeds'],why:'Seed → seedling → adult plant with flowers → new seeds. Then the cycle starts again.'},
 {d:'B',s:'K',v:'i:bee',q:'How do bees help with pollination?',o:['They carry pollen from one flower to another','They water the plants','They eat the roots'],why:'Pollen sticks to a bee’s hairy body. When it visits the next flower, pollen rubs off. This is called pollination.'},
 {d:'B',s:'A',v:'i:sycamore',q:'These are sycamore seeds. How are they dispersed?',o:['They spin away on the wind','Animals eat them and carry them','They float down rivers'],why:'Sycamore seeds have wings. They spin like helicopters and are dispersed by the wind, away from the parent tree.'},
 {d:'B',s:'A',v:'i:burr',q:'Burdock seeds are covered in tiny hooks. How are they dispersed?',o:['They catch on animals’ fur','They are blown by the wind','They explode out of the pod'],why:'The hooks stick to fur and clothes. The seeds fall off later, far from the parent plant.'},
 {d:'B',s:'K',q:'Which statement about nutrition is true?',o:['Humans cannot make their own food. They get nutrition from what they eat','Humans make their own food from sunlight, like plants','Humans only need water to stay healthy'],why:'Plants make their own food. Animals, including humans, cannot. They need the right types and amount of nutrition from what they eat.'},
 {d:'B',s:'K',v:'i:rice',q:'Rice, bread and pasta are a good source of…',o:['carbohydrates, which give us energy','protein for growing muscles','calcium for strong bones'],why:'Carbohydrates are our main energy food.'},
 {d:'B',s:'A',q:'Sam wants his lunch to contain protein for growth and repair. Which food should he add?',o:['Fish','Sweets','A fizzy drink'],why:'Fish contains protein. Protein helps the body grow and repair muscles.'},
 {d:'B',s:'K',v:'skel:skull',q:'What is the main job of the bone the arrow is pointing to?',o:['To protect the brain','To help us bend our legs','To help us digest food'],why:'The skull is a hard case of bone that protects the brain.'},
 {d:'B',s:'K',t:'two',q:'Which TWO are jobs of the human skeleton?',o:['Support','Protection of organs such as the heart','Digestion of food','Pumping blood'],why:'The skeleton gives support, protection and, working with muscles, movement.'},
 {d:'B',s:'A',q:'You bend your arm at the elbow. What makes the bones move?',o:['Muscles contract and pull on the bones','The bones move by themselves','Blood pushes the bones'],why:'Muscles are attached to bones. When a muscle contracts (gets shorter), it pulls on the bone and the arm bends.'},
 {d:'B',s:'A',q:'Which animal does NOT have a skeleton?',o:['A jellyfish','A cat','A frog'],why:'Jellyfish have soft bodies with no skeleton. Cats and frogs have skeletons inside their bodies.'},
 {d:'C',s:'K',v:'i:granite',q:'This rock is hard and is made of grains of different colours. Which rock is it?',o:['Granite','Chalk','Sandstone'],why:'Granite is a hard rock made of speckled crystals.'},
 {d:'C',s:'A',q:'Which rock would be best for a kitchen worktop? It must be hard and impermeable (it must not let water soak in).',o:['Granite','Chalk','Sandstone'],why:'Granite is very hard and does not let water in, so it is good for worktops. Chalk is soft and crumbly.'},
 {d:'C',s:'W',tb:[['Rock','Drops of water soaked up in 1 minute'],['Chalk','9'],['Granite','0'],['Sandstone','6'],['Marble','1']],q:'Amir dripped water onto four rocks. Which rock is the MOST permeable?',o:['Chalk','Granite','Sandstone'],why:'Chalk soaked up 9 drops, the most in the table. Rocks that let water soak in are permeable.'},
 {d:'C',s:'W',tb:[['Rock','Drops of water soaked up in 1 minute'],['Chalk','9'],['Granite','0'],['Sandstone','6'],['Marble','1']],q:'Use the table. Which rock would be best for a garden path that needs to stay dry?',o:['Granite','Chalk','Sandstone'],why:'Granite soaked up no water, so it is impermeable. A granite path would stay dry and strong.'},
 {d:'C',s:'W',q:'Amir wants his test to be a fair test. Which variable should he keep the same?',o:['The size of each piece of rock','The colour of each rock','The name of each rock'],why:'If one piece was much bigger, it could soak up more water just because of its size. Keeping the size the same makes it fair.'},
 {d:'C',s:'K',t:'order',q:'Put these steps in the correct order to describe how a fossil is formed.',o:['A sea animal dies and sinks to the seabed','It is covered by layers of mud and sand','Over millions of years, the layers turn into rock','The rock wears away and the fossil is found'],why:'Fossils are formed when things that have lived are trapped within rock. This takes millions of years.'},
 {d:'C',s:'K',v:'i:ammonite',q:'What is this?',o:['A fossil of a sea animal that lived long ago','A modern snail shell','A piece of metal'],why:'This is an ammonite fossil. Ammonites lived in the sea millions of years ago.'},
 {d:'C',s:'K',q:'Mary Anning lived about 200 years ago. Why is she famous?',o:['She found amazing fossils on the beach','She invented the light bulb','She was the first person in space'],why:'Mary Anning found fossils of sea reptiles, including an ichthyosaur, on the cliffs at Lyme Regis in England.'},
 {d:'C',s:'K',q:'What are soils made from?',o:['Tiny pieces of rock and organic matter (dead plants and animals)','Only sand','Melted ice'],why:'Soil is a mixture of tiny rock pieces, rotting plant and animal matter (called organic matter), air and water.'},
 {d:'C',s:'A',v:'soil:topsoil',q:'Which layer of soil is the arrow pointing to?',o:['Topsoil','Subsoil','Bedrock'],why:'Topsoil is the dark top layer. It has the most organic matter, so most plants grow their roots there.'},
 {d:'C',s:'W',v:'bars:Sandy=40,Clay=10,Garden=25',q:'The chart shows how many millilitres of water drained through three soils in 5 minutes. Which soil let the MOST water through?',o:['Sandy soil','Clay soil','Garden soil'],why:'The sandy soil bar is the tallest (40 ml). Sand has big gaps between its grains, so water drains through quickly.'},
 {d:'C',s:'A',t:'two',q:'Which TWO objects are made from rock?',o:['A slate roof tile','A marble statue','A wooden spoon','A plastic cup'],why:'Slate and marble are both rocks. Wood comes from trees and plastic is made in factories.'},
 {d:'P',s:'K',v:'see:dark',q:'In a completely dark room, Lily cannot see her ball. Why not?',o:['There is no light to reflect off the ball into her eyes','The ball has disappeared','Her eyes are closed'],why:'We need light to see things. Light reflects off objects into our eyes. Dark is the absence of light.'},
 {d:'P',s:'K',t:'two',q:'Which TWO are light sources?',o:['The Sun','A switched-on torch','A mirror','The Moon'],why:'Light sources make their own light. A mirror and the Moon only reflect light.'},
 {d:'P',s:'A',q:'Why should you never look directly at the Sun, even with sunglasses?',o:['Light from the Sun can damage your eyes','It will make you sneeze','It is too far away to see'],why:'Sunlight can permanently damage your eyes. Never look directly at the Sun.'},
 {d:'P',s:'K',q:'How is a shadow formed?',o:['An opaque object blocks the light from a light source','Light bounces off a mirror','A torch makes dark light'],why:'Light travels in straight lines. When an opaque object blocks it, a dark shadow forms behind the object.'},
 {d:'P',s:'W',tb:[['Distance from torch to puppet','Height of shadow'],['10 cm','40 cm'],['20 cm','24 cm'],['30 cm','16 cm'],['40 cm','12 cm']],q:'Tom moved a torch further away from a puppet and measured the shadow. What pattern do his results show?',o:['The further away the torch, the smaller the shadow','The further away the torch, the bigger the shadow','The shadow stayed the same size'],why:'As the distance goes up (10 → 40 cm), the shadow height goes down (40 → 12 cm).'},
 {d:'P',s:'W',tb:[['Distance from torch to puppet','Height of shadow'],['10 cm','40 cm'],['20 cm','24 cm'],['30 cm','16 cm'],['40 cm','12 cm']],q:'Use Tom’s pattern. Predict the shadow height if the torch was 50 cm away.',o:['About 10 cm','About 30 cm','About 50 cm'],why:'The shadow keeps getting smaller as the torch moves away, so at 50 cm it would be a little smaller than 12 cm.'},
 {d:'P',s:'K',v:'magnets:NN',q:'Two magnets are placed with their north poles facing. What will happen?',o:['The magnets push apart (repel)','The magnets pull together (attract)','Nothing at all'],why:'Like poles (north and north, or south and south) repel. Opposite poles attract.'},
 {d:'P',s:'A',t:'two',q:'Which TWO objects are made of magnetic materials?',o:['An iron nail','A steel paper clip','A plastic button','A wooden pencil'],why:'Magnets attract iron and steel. Plastic and wood are not magnetic.'},
 {d:'P',s:'K',q:'Which force can act at a distance, without contact between the two objects?',o:['Magnetic force','Friction','A push to open a door'],why:'A magnet can pull a paper clip from a distance. Friction and pushes need contact.'},
 {d:'P',s:'W',tb:[['Surface on the ramp','Distance the toy car travelled'],['Carpet','35 cm'],['Wood','90 cm'],['Sandpaper','20 cm'],['Plastic tray','120 cm']],q:'Children compared how a toy car moved on different surfaces. On which surface was there the MOST friction?',o:['Sandpaper','Plastic tray','Wood'],why:'The car travelled the shortest distance on sandpaper. The rough surface made the most friction, which slowed it down most.'},
 {d:'P',s:'W',q:'How could the children improve their investigation so the results are more reliable?',o:['Repeat each test three times and find the average','Use a different car each time','Change the height of the ramp each time'],why:'Repeating a test and working out the average makes results more trustworthy, because one odd result counts for less.'}
]};

window.SQ_GL.kg2 = {name:'KG2', year:'Year 1', level:'Starter', mins:25, intro:'Plants, animals and the human body, everyday materials, and seasonal changes.',
qs:[
 {d:'B',s:'K',v:'tree:trunk',q:'What is the name of the part of the tree the arrow is pointing to?',o:['Trunk','Root','Leaf'],why:'The trunk is the thick, woody stem of a tree. It holds the tree up.'},
 {d:'B',s:'K',v:'plant:petal',q:'What is the name of the part of the flower the arrow is pointing to?',o:['Petal','Root','Stem'],why:'Petals are the coloured parts of a flower.'},
 {d:'B',s:'K',v:'tree:winter',q:'This tree has lost all its leaves in winter. What kind of tree is it?',o:['Deciduous','Evergreen','A cactus'],why:'Deciduous trees drop their leaves in autumn and grow new ones in spring.'},
 {d:'B',s:'K',v:'i:holly',q:'Holly keeps its green leaves all year round. Which word describes holly?',o:['Evergreen','Deciduous','Wild flower'],why:'Evergreen plants keep their leaves all year round.'},
 {d:'B',s:'A',q:'Which of these is a wild plant?',o:['A dandelion growing in a field','A rose planted by a gardener','A tomato plant in a greenhouse'],why:'Wild plants grow by themselves. Nobody plants them.'},
 {d:'B',s:'K',v:'i:frog',q:'Which group of animals does a frog belong to?',o:['Amphibians','Reptiles','Fish'],why:'Frogs are amphibians. They start life in water and have smooth, damp skin.'},
 {d:'B',s:'K',t:'two',q:'Which TWO animals are mammals?',o:['A cow','A rabbit','A shark','A parrot'],why:'Mammals have hair or fur and feed their babies milk. A shark is a fish and a parrot is a bird.'},
 {d:'B',s:'K',v:'i:lizard',q:'What covers a lizard’s body?',o:['Dry scales','Feathers','Fur'],why:'Lizards are reptiles. Reptiles have dry, scaly skin.'},
 {d:'B',s:'A',v:'i:sheep',q:'A sheep eats only grass. What is a sheep?',o:['A herbivore','A carnivore','An omnivore'],why:'A herbivore eats only plants.'},
 {d:'B',s:'K',v:'i:ear',q:'Which sense do we use our ears for?',o:['Hearing','Smell','Taste'],why:'We hear with our ears.'},
 {d:'B',s:'K',v:'body:elbow',q:'Which part of the body is the arrow pointing to?',o:['Elbow','Knee','Shoulder'],why:'The elbow is the joint in the middle of your arm.'},
 {d:'C',s:'K',v:'i:spoon',q:'Which material is this spoon made from?',o:['Metal','Wood','Fabric'],why:'This spoon is made of metal. It is shiny, hard and strong.'},
 {d:'C',s:'K',q:'Which of these is a material, not an object?',o:['Wood','A chair','A cup'],why:'Wood is a material. A chair and a cup are objects made from materials.'},
 {d:'C',s:'A',q:'Which material is best for a window?',o:['Glass, because it is transparent','Wood, because it is hard','Brick, because it is strong'],why:'Transparent means you can see through it. Windows need to let light in.'},
 {d:'C',s:'W',tb:[['Material','Did water soak through?'],['Paper','Yes'],['Foil','No'],['Tissue','Yes'],['Plastic bag','No']],q:'Children tested which materials would keep a toy dry. Which TWO materials are waterproof?',t:'two',o:['Foil','Plastic bag','Paper','Tissue'],why:'Water did not soak through the foil or the plastic bag, so they are waterproof.'},
 {d:'C',s:'A',q:'Why is a raincoat made from plastic or rubber?',o:['It is waterproof','It is transparent','It is magnetic'],why:'Rain cannot soak through plastic or rubber, so you stay dry.'},
 {d:'P',s:'K',v:'season:winter',q:'Which season does this picture show?',o:['Winter','Summer','Spring'],why:'The trees are bare and there is snow on the ground.'},
 {d:'P',s:'K',q:'In which season are the days longest?',o:['Summer','Winter','Autumn'],why:'In summer the Sun rises early and sets late, so there are many hours of daylight.'},
 {d:'P',s:'W',v:'bars:Spring=12,Summer=16,Autumn=11,Winter=8',q:'The chart shows how many hours of daylight there are in each season in the UK. Which season has the shortest days?',o:['Winter','Summer','Spring'],why:'The winter bar is the shortest: only 8 hours of daylight.'},
 {d:'P',s:'K',t:'order',q:'Put the seasons in the correct order. Start with spring.',o:['Spring','Summer','Autumn','Winter'],why:'The seasons go spring, summer, autumn, winter, and then spring again.'}
]};

window.SQ_GL.g1 = {name:'Grade 1', year:'Year 2', level:'Starter', mins:35, intro:'Living things and their habitats, plants, animals and humans, and uses of everyday materials.',
qs:[
 {d:'B',s:'K',q:'Which of these has never been alive?',o:['A plastic button','A wooden table','A leaf'],why:'Plastic is made in factories. Wood and leaves come from trees, which were once alive.'},
 {d:'B',s:'K',v:'i:leaf',q:'This dry leaf has fallen from a tree. Which word describes it now?',o:['Dead','Never alive','Alive'],why:'The leaf was once alive on the tree. Now it has fallen and dried up, so it is dead.'},
 {d:'B',s:'K',v:'scene:desert',q:'Which habitat is this?',o:['A desert','An ocean','A woodland'],why:'A desert is a very dry habitat with sand and very little rain.'},
 {d:'B',s:'A',v:'i:arctic',q:'How is a polar bear suited to its Arctic habitat?',o:['Thick white fur keeps it warm and hidden in the snow','Thin skin keeps it cool','Big ears help it lose heat'],why:'Thick fur and fat keep the polar bear warm. White fur helps it hide in the snow.'},
 {d:'B',s:'K',v:'scene:log',q:'Which animal are you most likely to find living under this log?',o:['A woodlouse','A shark','A camel'],why:'Under a log it is dark and damp. Woodlice live in micro-habitats like this.'},
 {d:'B',s:'K',q:'What is a micro-habitat?',o:['A very small habitat, such as under a stone','A huge ocean','A zoo'],why:'A micro-habitat is a very small habitat, like under a log, a stone or a pile of leaves.'},
 {d:'B',s:'K',v:'chain:clover,rabbit,badger',q:'Look at the food chain. What is the rabbit’s source of food?',o:['Clover','The badger','Water'],why:'The arrow shows that the clover is eaten by the rabbit.'},
 {d:'B',s:'A',q:'In a wood, foxes eat rabbits. What would happen to the foxes if all the rabbits disappeared?',o:['They would have less food','They would have more food','Nothing would change for them'],why:'Animals depend on each other for food. Without rabbits, the foxes would have less to eat.'},
 {d:'B',s:'K',t:'two',q:'Which TWO things do seeds and bulbs need to grow into healthy plants?',o:['Water','A suitable temperature','Salt','Darkness'],why:'Seeds and bulbs need water, light and a suitable temperature to grow and stay healthy.'},
 {d:'B',s:'W',v:'i:cresspale',q:'This cress was kept in a dark cupboard. It is pale and thin. What does this show?',o:['Plants need light to grow green and healthy','Plants grow best in the dark','Cress does not need water'],why:'Without light, the cress could not grow properly, so it is pale and weak.'},
 {d:'B',s:'W',v:'bars:Day2=0,Day6=3,Day10=8',q:'The chart shows the height of a bean plant in centimetres. How tall was it on day 10?',o:['8 cm','3 cm','10 cm'],why:'The bar for Day 10 reaches 8.'},
 {d:'B',s:'W',v:'bars:Day2=0,Day6=3,Day10=8',q:'Look at the chart again. What pattern does it show?',o:['The plant grew taller over time','The plant got shorter over time','The plant stayed the same height'],why:'Each bar is taller than the one before, so the plant grew taller over time.'},
 {d:'B',s:'K',t:'order',q:'Put the stages of human growth in the correct order. Start with the youngest.',o:['Baby','Child','Teenager','Adult'],why:'Humans grow from babies into children, then teenagers, then adults.'},
 {d:'B',s:'K',q:'Animals have offspring that grow into adults. What are the offspring of a sheep called?',o:['Lambs','Calves','Chicks'],why:'Baby sheep are lambs. Baby cows are calves and baby hens are chicks.'},
 {d:'B',s:'A',v:'i:caterpillar',q:'A caterpillar hatches from an egg. What will it grow into?',o:['A butterfly','A spider','A beetle'],why:'A caterpillar becomes a chrysalis, and then an adult butterfly.'},
 {d:'B',s:'K',t:'two',q:'Which TWO things do all animals, including humans, need to survive?',o:['Water','Food','Toys','A television'],why:'Animals need water, food and air to survive.'},
 {d:'B',s:'A',q:'Why is it important for humans to exercise?',o:['It keeps our heart and muscles healthy','It makes us need less water','It stops us growing'],why:'Exercise makes the heart and muscles stronger and keeps us healthy.'},
 {d:'B',s:'A',v:'i:washhands',q:'Why should you wash your hands before eating?',o:['To wash away germs that could make you ill','To make your hands warm','To make your food taste better'],why:'Good hygiene, like washing your hands, stops germs getting into your body.'},
 {d:'B',s:'A',q:'Which of these is the healthiest snack?',o:['An apple','A bag of sweets','A chocolate bar'],why:'Fruit is part of a healthy diet. Sweets and chocolate have lots of sugar.'},
 {d:'C',s:'A',q:'Which material is the most suitable for a saucepan?',o:['Metal, because it is strong and heats up well','Paper, because it is light','Chocolate, because it melts'],why:'Metal is strong and lets heat through, so it is suitable for cooking.'},
 {d:'C',s:'A',q:'Why would paper be a bad material for an umbrella?',o:['Paper is not waterproof, so it would go soggy','Paper is too heavy','Paper is magnetic'],why:'Paper soaks up water. An umbrella must be waterproof.'},
 {d:'C',s:'K',q:'You press a sponge with your hands and it gets smaller. What are you doing to it?',o:['Squashing it','Stretching it','Twisting it'],why:'Squashing means pressing something so it changes shape and gets smaller.'},
 {d:'C',s:'K',t:'two',q:'Which TWO objects can be stretched easily?',o:['An elastic band','A rubber balloon','A brick','A glass marble'],why:'Elastic bands and balloons are made of rubber, which stretches.'},
 {d:'C',s:'K',v:'i:playdough',q:'How can you change the shape of play dough?',o:['By squashing, bending, twisting and stretching it','By looking at it','By putting it in a box'],why:'Pushing and pulling, like squashing and stretching, change the shape of soft materials.'},
 {d:'C',s:'A',q:'Wood is used to make many things. Which object is NOT usually made from wood?',o:['A window pane','A table','A pencil'],why:'A window pane is made of glass so that light can pass through.'},
 {d:'C',s:'W',tb:[['Material','Number of coins it held before bending'],['Paper','2'],['Card','9'],['Tissue','0']],q:'Children made bridges from different materials and added coins. Which material made the strongest bridge?',o:['Card','Paper','Tissue'],why:'The card bridge held 9 coins, the most.'},
 {d:'C',s:'W',tb:[['Material','Number of coins it held before bending'],['Paper','2'],['Card','9'],['Tissue','0']],q:'To make it a fair test, what should be the same for every bridge?',o:['The size of each piece of material','The colour of each material','The name of each material'],why:'If one piece was bigger, it might hold more coins just because of its size.'},
 {d:'C',s:'K',q:'Charles Macintosh lived about 200 years ago. What is he famous for?',o:['Inventing a waterproof material for raincoats','Inventing the bicycle','Finding fossils'],why:'Charles Macintosh found a way to make cloth waterproof. Raincoats are still called macs!'},
 {d:'C',s:'K',q:'John McAdam is famous for a new way of making…',o:['roads','glass','paper'],why:'John McAdam found a better way to build smooth, strong roads.'},
 {d:'C',s:'A',q:'Why are most bottles for drinks made from plastic or glass?',o:['They are waterproof and do not leak','They are soft and soak up water','They are magnetic'],why:'Bottles must hold liquids without leaking, so they are made from waterproof materials.'}
]};

window.SQ_GL.g3 = {name:'Grade 3', year:'Year 4', level:'Level 9', mins:50, intro:'Living things and habitats, digestion and teeth, states of matter, sound, and electricity.',
qs:[
 {d:'B',s:'K',q:'Which animal is an invertebrate?',o:['A snail','A frog','A sparrow'],why:'An invertebrate has no backbone. Snails have no backbone.'},
 {d:'B',s:'W',tb:[['Question','Yes','No'],['1. Does it have legs?','Go to question 2','Earthworm'],['2. Does it have more than 6 legs?','Spider','Ladybird']],q:'Use the classification key. An animal has legs, but not more than 6. What is it?',o:['Ladybird','Spider','Earthworm'],why:'Question 1: yes, it has legs. Question 2: no, not more than 6. The key gives ladybird.'},
 {d:'B',s:'W',tb:[['Question','Yes','No'],['1. Does it have legs?','Go to question 2','Earthworm'],['2. Does it have more than 6 legs?','Spider','Ladybird']],q:'Use the same key. Which animal has no legs?',o:['Earthworm','Spider','Ladybird'],why:'If the answer to question 1 is no, the key gives earthworm.'},
 {d:'B',s:'K',t:'two',q:'Which TWO animals are vertebrates?',o:['A trout','A robin','A snail','A worm'],why:'Vertebrates have a backbone. Fish and birds are vertebrates.'},
 {d:'B',s:'A',q:'A new road is built through a forest. How might this change the environment for animals?',o:['Their habitat is split, so finding food and shelter is harder','Every animal gets more food','Nothing changes for the animals'],why:'Environments can change, and this can put living things in danger.'},
 {d:'B',s:'A',q:'Which action would have a positive effect on a local environment?',o:['Planting wildflowers and making a pond','Dropping litter','Cutting down all the hedges'],why:'Wildflowers and ponds give food, water and shelter to many living things.'},
 {d:'B',s:'K',v:'gut:stomach',q:'Which part of the digestive system is the arrow pointing to?',o:['Stomach','Small intestine','Oesophagus'],why:'The stomach churns food and mixes it with acid and digestive juices.'},
 {d:'B',s:'K',t:'order',q:'Put the parts of the digestive system in the order that food passes through them.',o:['Mouth','Oesophagus','Stomach','Small intestine','Large intestine'],why:'Food goes from the mouth, down the oesophagus, into the stomach, then the small intestine and the large intestine.'},
 {d:'B',s:'K',q:'In which organ are most nutrients absorbed into the blood?',o:['Small intestine','Oesophagus','Mouth'],why:'Nutrients pass through the walls of the small intestine into the blood.'},
 {d:'B',s:'K',v:'jaw:canine',q:'Which type of tooth is the arrow pointing to?',o:['Canine','Incisor','Molar'],why:'Canines are pointed teeth for gripping and tearing food.'},
 {d:'B',s:'A',q:'Lions have long, sharp canine teeth. What does this tell you about their diet?',o:['They eat meat and need to grip and tear it','They eat only grass','They only drink water'],why:'Carnivores like lions use long canines to grip and tear meat.'},
 {d:'B',s:'K',q:'What is the main function of molars?',o:['To grind and chew food','To cut food','To tear food'],why:'Molars are wide, flat teeth at the back of the mouth for grinding.'},
 {d:'B',s:'K',q:'In the food chain grass → rabbit → fox, which living thing is the producer?',o:['Grass','Rabbit','Fox'],why:'A producer is a green plant that makes its own food. Every food chain starts with a producer.'},
 {d:'B',s:'A',q:'In the food chain grass → grasshopper → frog → heron, which animal is the prey of the frog?',o:['The grasshopper','The heron','The grass'],why:'The frog eats the grasshopper, so the grasshopper is its prey.'},
 {d:'B',s:'A',q:'In the food chain grass → grasshopper → frog → heron, all the frogs disappear. What would happen to the number of grasshoppers?',o:['It would increase','It would decrease','It would stay the same'],why:'Frogs are the grasshoppers’ predator. With no frogs to eat them, there would be more grasshoppers.'},
 {d:'B',s:'W',v:'bars:Woodlice=14,Worms=9,Snails=5,Beetles=3',q:'Children counted the animals they found under a log. Which animal was found most often?',o:['Woodlice','Worms','Beetles'],why:'The woodlice bar is the tallest: 14 were found.'},
 {d:'C',s:'K',t:'two',q:'Which TWO are gases?',o:['The air inside a balloon','Water vapour','Ice','Orange juice'],why:'Air and water vapour are gases. Ice is a solid and juice is a liquid.'},
 {d:'C',s:'K',v:'particles:liquid',q:'The diagram shows how particles are arranged. Which state of matter does it show?',o:['Liquid','Solid','Gas'],why:'In a liquid, the particles are close together but can move past each other, so liquids can flow.'},
 {d:'C',s:'K',q:'At what temperature does pure water freeze?',o:['0 °C','100 °C','37 °C'],why:'Water freezes at 0 degrees Celsius.'},
 {d:'C',s:'A',v:'thermo:100',q:'A pan of water is heated until the thermometer shows this temperature. What is happening to the water?',o:['It is boiling','It is freezing','It is melting'],why:'Water boils at 100 °C and changes into water vapour.'},
 {d:'C',s:'A',q:'Chocolate left in a hot car becomes runny. What is this change of state called?',o:['Melting','Freezing','Condensing'],why:'Heat makes the solid chocolate melt into a liquid.'},
 {d:'C',s:'K',q:'What is evaporation?',o:['A liquid changing into a gas','A gas changing into a liquid','A liquid changing into a solid'],why:'When water evaporates, it changes into water vapour, a gas.'},
 {d:'C',s:'A',q:'Water droplets form on the inside of a cold window. What is this called?',o:['Condensation','Evaporation','Melting'],why:'Water vapour in the air cools on the cold glass and condenses into liquid water.'},
 {d:'C',s:'W',tb:[['Day','Weather','Time for a puddle to dry'],['Monday','Warm and still','3 hours'],['Tuesday','Cool and cloudy','6 hours'],['Wednesday','Warm and windy','1 hour']],q:'Which conclusion do these results support?',o:['Puddles evaporate fastest when it is warm and windy','Puddles evaporate fastest when it is cool','Wind makes no difference to evaporation'],why:'The puddle dried fastest (1 hour) on the warm, windy day. The rate of evaporation depends on temperature and wind.'},
 {d:'C',s:'K',t:'order',q:'Put the stages of the water cycle in the correct order. Start with the sea.',o:['Water evaporates from the sea','Water vapour cools and condenses to form clouds','Water falls as rain (precipitation)','Rainwater flows back into rivers and the sea'],why:'Evaporation, condensation, precipitation and collection make the water cycle.'},
 {d:'C',s:'K',v:'wcycle:condensation',q:'Which part of the water cycle is happening where the arrow points?',o:['Condensation','Evaporation','Precipitation'],why:'High in the sky, water vapour cools and condenses into tiny droplets that form clouds.'},
 {d:'C',s:'W',q:'Which piece of equipment should you use to measure the temperature of water?',o:['A thermometer','A ruler','A stopwatch'],why:'A thermometer measures temperature in degrees Celsius (°C).'},
 {d:'C',s:'A',q:'Why does washing dry faster on a sunny, windy day?',o:['The water evaporates more quickly','The water freezes more quickly','The water condenses more quickly'],why:'Warmth and wind increase the rate of evaporation.'},
 {d:'C',s:'W',v:'bars:Fridge=60,Table=25,Window=10',q:'The chart shows how many minutes an ice cube took to melt in three places. Where did it melt fastest?',o:['On a sunny window','On the kitchen table','In the fridge'],why:'The shortest bar (10 minutes) is for the window, the warmest place.'},
 {d:'C',s:'A',q:'Which of these is a solid?',o:['Sand','Milk','Steam'],why:'Sand can be poured, but each grain is a solid that keeps its own shape.'},
 {d:'P',s:'K',q:'How are all sounds made?',o:['Something vibrates','Something gets hot','Something gives out light'],why:'All sounds are made by vibrations.'},
 {d:'P',s:'K',q:'How does the sound of a drum reach your ear?',o:['Vibrations travel through the air to your ear','Light carries it to your ear','The drum moves towards your ear'],why:'Vibrations from a sound source travel through a medium, such as air, to the ear.'},
 {d:'P',s:'A',v:'drums',q:'The drums are the same except for their size. Which drum makes the lowest-pitched sound?',o:['A, the largest drum','B, the middle drum','C, the smallest drum'],why:'A larger drum skin vibrates more slowly, which makes a lower pitch.'},
 {d:'P',s:'A',q:'A guitar string is tightened. What happens to the pitch of its sound?',o:['It gets higher','It gets lower','It stays the same'],why:'A tighter string vibrates faster, so the pitch is higher.'},
 {d:'P',s:'W',v:'bottles',q:'Ben blows across the tops of these bottles. Which bottle makes the highest-pitched note?',o:['C, with the most water','A, with the least water','They all make the same note'],why:'The air inside vibrates. Bottle C has the least air, so it makes the highest note.'},
 {d:'P',s:'A',q:'Why does a sound get fainter as you move away from it?',o:['The vibrations get weaker as they travel further','The sound changes pitch','The sound turns into light'],why:'Sounds get fainter as the distance from the sound source increases.'},
 {d:'P',s:'W',tb:[['Distance from the radio','Sound level (dB)'],['1 m','70'],['2 m','64'],['4 m','58'],['8 m','52']],q:'Mia used a data logger to measure the sound of a radio. What pattern do her results show?',o:['The further away, the quieter the sound','The further away, the louder the sound','Distance makes no difference'],why:'As the distance increases (1 m → 8 m), the sound level decreases (70 → 52 dB).'},
 {d:'P',s:'K',t:'two',q:'Which TWO appliances normally run on mains electricity?',o:['A fridge','A washing machine','A torch','A TV remote control'],why:'Fridges and washing machines plug into the mains. Torches and remote controls use batteries.'},
 {d:'P',s:'K',v:'circuit:gap',q:'Will the bulb in this circuit light?',o:['No, because the circuit is not complete','Yes, because there is a cell','Yes, but only dimly'],why:'A lamp only lights if it is part of a complete loop with a cell.'},
 {d:'P',s:'A',v:'circuit:gap',q:'Which object could be placed in the gap to make the bulb light?',o:['A metal paper clip','A plastic ruler','A wooden pencil'],why:'Metals are good electrical conductors, so the paper clip would complete the circuit.'},
 {d:'P',s:'K',q:'Which material is an electrical insulator?',o:['Plastic','Copper','Steel'],why:'Plastic does not let electricity pass through it.'},
 {d:'P',s:'K',q:'What does a switch do in a circuit?',o:['It opens and closes the circuit','It makes the cell bigger','It changes the colour of the bulb'],why:'When a switch is open there is a gap, so the lamp goes off. When it is closed, the circuit is complete.'},
 {d:'P',s:'A',q:'Why are electrical wires covered in plastic?',o:['Plastic is an insulator, so it keeps us safe','Plastic makes electricity flow faster','Plastic makes the wire magnetic'],why:'The plastic coating is an insulator, so we can touch the wire safely.'},
 {d:'P',s:'W',tb:[['Material in the gap','Did the bulb light?'],['Foil','Yes'],['Rubber','No'],['Steel spoon','Yes'],['Wood','No']],q:'Children tested materials in a circuit. Which conclusion do the results support?',o:['Metals are good electrical conductors','All materials are conductors','Rubber is a good conductor'],why:'The bulb only lit with foil and steel, which are both metals.'}
]};

window.SQ_GL.g4 = {name:'Grade 4', year:'Year 5', level:'Level 10', mins:50, intro:'Life cycles, human development, properties and changes of materials, Earth and space, and forces.',
qs:[
 {d:'B',s:'K',t:'order',q:'Put the stages of a butterfly’s life cycle in the correct order. Start with the egg.',o:['Egg','Larva (caterpillar)','Pupa (chrysalis)','Adult butterfly'],why:'This is called complete metamorphosis.'},
 {d:'B',s:'K',q:'Which animal goes through metamorphosis?',o:['A frog','A human','A cat'],why:'A frog changes from a tadpole into a froglet and then an adult frog. This is metamorphosis.'},
 {d:'B',s:'K',v:'cycle:frogspawn,tadpole,frog',q:'Look at the life cycle of a frog. Which group of animals do frogs belong to?',o:['Amphibians','Mammals','Reptiles'],why:'Amphibians begin life in water and can live on land as adults.'},
 {d:'B',s:'K',q:'What is pollination?',o:['When pollen is moved from one flower to another','When a seed starts to grow','When a plant takes in water'],why:'Pollination is part of sexual reproduction in plants. It happens before seeds are made.'},
 {d:'B',s:'A',q:'Strawberry plants send out runners that grow into new plants. What type of reproduction is this?',o:['Asexual reproduction','Sexual reproduction','Metamorphosis'],why:'Only one parent plant is needed, so this is asexual reproduction.'},
 {d:'B',s:'A',q:'Why do many flowers have brightly coloured petals and sweet nectar?',o:['To attract insects for pollination','To scare animals away','To keep the plant warm'],why:'Insects visit for nectar and carry pollen between flowers.'},
 {d:'B',s:'K',q:'How is the life cycle of most mammals different from the life cycle of a bird?',o:['Most mammals give birth to live young; birds lay eggs','Mammals lay eggs; birds give birth to live young','There is no difference'],why:'Most mammal babies grow inside their mother. Bird chicks hatch from eggs.'},
 {d:'B',s:'K',q:'Jane Goodall spent many years studying the behaviour of which animals?',o:['Chimpanzees','Penguins','Sharks'],why:'Jane Goodall studied wild chimpanzees in Tanzania.'},
 {d:'B',s:'K',t:'order',q:'Put the stages of human development in the correct order.',o:['Baby','Child','Adolescent','Adult','Elderly'],why:'Humans develop from babies to old age.'},
 {d:'B',s:'K',q:'What is puberty?',o:['The time when a child’s body starts to change into an adult’s body','The time when a baby is born','The time when people become elderly'],why:'Puberty usually happens between about 8 and 14 years old.'},
 {d:'B',s:'W',tb:[['Animal','Gestation period'],['Mouse','3 weeks'],['Cat','9 weeks'],['Human','9 months'],['Elephant','22 months']],q:'Which animal has the longest gestation period?',o:['Elephant','Human','Mouse'],why:'An elephant’s gestation period is 22 months, the longest in the table.'},
 {d:'B',s:'W',tb:[['Animal','Gestation period'],['Mouse','3 weeks'],['Cat','9 weeks'],['Human','9 months'],['Elephant','22 months']],q:'Which pattern do these results suggest?',o:['Larger animals usually have longer gestation periods','Smaller animals usually have longer gestation periods','All animals have the same gestation period'],why:'As the animals get bigger, the gestation period gets longer.'},
 {d:'C',s:'K',q:'Which word describes a material that lets light pass through it so you can see clearly?',o:['Transparent','Opaque','Magnetic'],why:'Transparent materials, like clear glass, let light through.'},
 {d:'C',s:'K',q:'Which material is the best thermal insulator?',o:['Wool','Copper','Steel'],why:'Wool traps air, which slows down the movement of heat.'},
 {d:'C',s:'A',q:'Why are saucepans made of metal, but with plastic handles?',o:['Metal is a thermal conductor; plastic is a thermal insulator','Plastic is a thermal conductor; metal is an insulator','Metal is soft and plastic is hard'],why:'Metal lets heat through to cook the food. The plastic handle stops your hand getting burnt.'},
 {d:'C',s:'K',q:'Salt dissolves in water. What is the mixture called?',o:['A solution','A solid','A gas'],why:'When a solid dissolves in a liquid, it forms a solution.'},
 {d:'C',s:'K',q:'Which of these is insoluble in water?',o:['Sand','Salt','Sugar'],why:'Sand does not dissolve in water. Salt and sugar do.'},
 {d:'C',s:'K',v:'separate:filter',q:'Which method of separating is shown?',o:['Filtering','Evaporating','Sieving'],why:'Filter paper lets the liquid through but traps the insoluble solid.'},
 {d:'C',s:'A',q:'How could you recover the salt from salty water?',o:['Evaporate the water','Use a magnet','Use a sieve'],why:'When the water evaporates, the salt is left behind.'},
 {d:'C',s:'A',q:'How could you separate iron filings from sand?',o:['Use a magnet','Dissolve them in water','Use a sieve with big holes'],why:'Iron is magnetic, so the magnet attracts the iron filings and leaves the sand behind.'},
 {d:'C',s:'K',t:'two',q:'Which TWO changes are reversible?',o:['Melting chocolate','Dissolving sugar in water','Burning wood','Baking a cake'],why:'Melting and dissolving can be reversed. Burning and baking make new materials.'},
 {d:'C',s:'K',q:'Which change is irreversible and makes a new material?',o:['Burning paper','Freezing water','Melting ice'],why:'Burning produces new materials, such as ash and smoke. It cannot be reversed.'},
 {d:'C',s:'A',q:'Bicarbonate of soda is mixed with vinegar and it fizzes. What does the fizzing show?',o:['A new material, a gas, is being made','The vinegar is boiling','Nothing has changed'],why:'The bubbles are carbon dioxide, a new material. This is an irreversible change.'},
 {d:'C',s:'W',tb:[['Water temperature','Time for sugar to dissolve'],['20 °C','90 seconds'],['40 °C','60 seconds'],['60 °C','35 seconds'],['80 °C','15 seconds']],q:'Which conclusion do these results support?',o:['Sugar dissolves faster in warmer water','Sugar dissolves faster in colder water','Temperature makes no difference'],why:'As the temperature goes up, the time to dissolve goes down.'},
 {d:'C',s:'W',tb:[['Water temperature','Time for sugar to dissolve'],['20 °C','90 seconds'],['40 °C','60 seconds'],['60 °C','35 seconds'],['80 °C','15 seconds']],q:'Which variable did the children change in this investigation?',o:['The temperature of the water','The amount of sugar','The type of sugar'],why:'The temperature is the only thing that changes in the table.'},
 {d:'C',s:'K',q:'Ruth Benerito was a chemist. What is she famous for?',o:['Making cotton that does not crease easily','Inventing the telephone','Discovering gravity'],why:'Ruth Benerito found a way to make wrinkle-free cotton.'},
 {d:'P',s:'K',t:'order',q:'Put these planets in order, starting with the one closest to the Sun.',o:['Mercury','Venus','Earth','Mars'],why:'The order from the Sun is Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune.'},
 {d:'P',s:'K',q:'Why do we have day and night?',o:['The Earth rotates on its axis','The Sun moves around the Earth','The Moon blocks the Sun'],why:'As the Earth rotates, each place faces the Sun (day), then faces away (night).'},
 {d:'P',s:'K',q:'About how long does it take the Earth to orbit the Sun once?',o:['365 days','24 hours','28 days'],why:'One orbit of the Sun takes about 365¼ days, which is one year.'},
 {d:'P',s:'K',q:'What does the Moon orbit?',o:['The Earth','The Sun only','Mars'],why:'The Moon orbits the Earth about once a month.'},
 {d:'P',s:'K',v:'sunpath:rise',q:'In which direction does the Sun appear to rise?',o:['East','West','North'],why:'The Sun appears to rise in the east and set in the west.'},
 {d:'P',s:'A',q:'Why does the Sun appear to move across the sky during the day?',o:['Because the Earth is rotating','Because the Sun orbits the Earth','Because the clouds move it'],why:'The Sun does not move across the sky. The Earth’s rotation makes it look as if it does.'},
 {d:'P',s:'K',q:'What shape are the Sun, Earth and Moon?',o:['Approximately spherical','Flat discs','Cubes'],why:'The Sun, Earth and Moon are approximately spherical bodies.'},
 {d:'P',s:'W',tb:[['Time of day','Length of a stick’s shadow'],['9 am','120 cm'],['12 noon','40 cm'],['3 pm','110 cm']],q:'When was the shadow shortest?',o:['12 noon','9 am','3 pm'],why:'At noon the Sun is highest in the sky, so the shadow is shortest.'},
 {d:'P',s:'K',q:'Long ago, many people believed the Earth was at the centre of everything. Which scientist argued that the Earth orbits the Sun?',o:['Nicolaus Copernicus','Isaac Newton','Charles Darwin'],why:'About 500 years ago, Copernicus argued that the planets orbit the Sun.'},
 {d:'P',s:'K',t:'two',q:'Which TWO statements about the Moon are true?',o:['It orbits the Earth','It reflects light from the Sun','It makes its own light','It orbits Mars'],why:'The Moon is not a light source. It reflects sunlight as it orbits the Earth.'},
 {d:'P',s:'K',q:'What is gravity?',o:['A force that pulls objects towards the Earth','A force that pushes objects up','A type of friction'],why:'Unsupported objects fall towards the Earth because of gravity.'},
 {d:'P',s:'K',q:'What unit is force measured in?',o:['Newtons (N)','Metres (m)','Litres (l)'],why:'Force is measured in newtons using a force meter.'},
 {d:'P',s:'A',v:'forces:parachute',q:'Which force slows the parachute down?',o:['Air resistance','Gravity','Magnetism'],why:'Air resistance acts against the falling parachute. A large canopy creates more air resistance.'},
 {d:'P',s:'A',q:'Why are boats and fish streamlined?',o:['To reduce water resistance','To increase friction','To make them heavier'],why:'A streamlined shape lets water flow past easily, so there is less water resistance.'},
 {d:'P',s:'A',q:'Which force slows a bicycle down when the brakes are used?',o:['Friction','Magnetism','Air resistance only'],why:'The brake pads rub against the wheel, creating friction.'},
 {d:'P',s:'W',tb:[['Size of parachute canopy','Time to fall (seconds)'],['20 cm','1.2'],['30 cm','1.8'],['40 cm','2.5'],['50 cm','3.1']],q:'What pattern do these results show?',o:['The larger the canopy, the longer it took to fall','The larger the canopy, the faster it fell','Canopy size made no difference'],why:'A larger canopy has more air resistance, so it falls more slowly.'},
 {d:'P',s:'W',q:'The children dropped each parachute three times and worked out the average. Why?',o:['To make their results more reliable','To make the test more fun','To change the size of the canopy'],why:'Repeating measurements and finding the average makes results more reliable.'},
 {d:'P',s:'W',q:'Which piece of equipment is used to measure force?',o:['A force meter','A thermometer','A measuring jug'],why:'A force meter (newton meter) measures forces in newtons.'},
 {d:'P',s:'K',v:'lever:far',q:'This simple machine helps lift a heavy box. What is it called?',o:['A lever','A pulley','A gear'],why:'A lever is a bar that turns on a pivot. It allows a smaller force to lift a bigger load.'},
 {d:'P',s:'A',v:'pulley',q:'How does a pulley help someone lift a heavy load?',o:['It allows a smaller force to have a greater effect','It makes the load lighter','It removes gravity'],why:'Pulleys change the direction of a force, and some let a smaller force lift a heavy load.'},
 {d:'P',s:'A',v:'gears',q:'What do gears do?',o:['Change the speed or direction of turning','Make things magnetic','Stop all friction'],why:'Gears are wheels with teeth. When one turns, it turns the next one.'},
 {d:'P',s:'K',q:'Which scientist is famous for his ideas about gravity?',o:['Isaac Newton','Thomas Edison','Charles Darwin'],why:'Isaac Newton explained gravity. The unit of force, the newton, is named after him.'},
 {d:'C',s:'W',q:'Leo wants to find out which material is the best thermal insulator. Which is the best plan?',o:['Wrap identical cups of hot water in different materials and measure the temperature every 5 minutes','Touch each material and guess','Wrap one cup and leave the others'],why:'A fair test changes only the material, then measures the temperature with a thermometer at regular intervals.'},
 {d:'P',s:'W',q:'Amy tests how the height of a ramp affects how far a toy car travels. Which variable is she changing?',o:['The height of the ramp','The distance the car travels','The type of toy car'],why:'The variable you change is the one you choose to test: here, the ramp height. The distance is what she measures.'}
]};

window.SQ_GL.g5 = {name:'Grade 5', year:'Year 6', level:'Level 11', mins:55, intro:'Classification, the circulatory system, evolution and inheritance, light, electricity, and materials revision.',
qs:[
 {d:'B',s:'K',q:'Which scientist developed the system for naming and classifying living things that we still use today?',o:['Carl Linnaeus','Isaac Newton','Marie Curie'],why:'Carl Linnaeus gave each living thing a two-part scientific name and sorted them into groups.'},
 {d:'B',s:'K',q:'Which of these are microorganisms?',o:['Bacteria','Beetles','Ferns'],why:'Microorganisms, such as bacteria, are too small to see without a microscope.'},
 {d:'B',s:'K',t:'two',q:'Which TWO characteristics do all mammals share?',o:['They have hair or fur','They feed their young on milk','They lay eggs in water','They breathe with gills'],why:'All mammals have hair or fur and feed their young on milk.'},
 {d:'B',s:'A',q:'A bat has wings and can fly. Which group of animals does it belong to?',o:['Mammals','Birds','Insects'],why:'Bats have fur and feed their young on milk, so they are mammals.'},
 {d:'B',s:'A',q:'Why are mushrooms not classified as plants?',o:['They cannot make their own food from sunlight','They grow in soil','They are too small'],why:'Mushrooms are fungi. Fungi feed on living or dead material instead of making their own food.'},
 {d:'B',s:'W',tb:[['Question','Yes','No'],['1. Does it have a backbone?','Go to question 2','Go to question 3'],['2. Does it have feathers?','Bird','Mammal'],['3. Does it have 8 legs?','Spider','Insect']],q:'Use the classification key. An animal has no backbone and has 6 legs. What is it?',o:['An insect','A spider','A mammal'],why:'Question 1: no, so go to question 3. It does not have 8 legs, so it is an insect.'},
 {d:'B',s:'W',tb:[['Question','Yes','No'],['1. Does it have a backbone?','Go to question 2','Go to question 3'],['2. Does it have feathers?','Bird','Mammal'],['3. Does it have 8 legs?','Spider','Insect']],q:'Use the same key. An animal has a backbone and fur, but no feathers. What is it?',o:['A mammal','A bird','An insect'],why:'Question 1: yes, go to question 2. No feathers, so it is a mammal.'},
 {d:'B',s:'A',q:'Which action best stops harmful microorganisms from spreading?',o:['Washing your hands with soap','Sharing drinking cups','Sneezing into your hands'],why:'Soap and water wash away germs. Catch sneezes in a tissue.'},
 {d:'B',s:'K',v:'heart:heart',q:'Which organ is the arrow pointing to?',o:['The heart','The lungs','The stomach'],why:'The heart is a muscle in the chest that pumps blood around the body.'},
 {d:'B',s:'K',q:'What is the main function of the heart?',o:['To pump blood around the body','To digest food','To take in oxygen from the air'],why:'The heart pumps blood through blood vessels to every part of the body.'},
 {d:'B',s:'K',q:'Which blood vessels carry blood away from the heart?',o:['Arteries','Veins','Capillaries only'],why:'Arteries carry blood away from the heart. Veins carry blood back to it.'},
 {d:'B',s:'K',t:'order',q:'Put these steps in order to describe how blood travels through the circulatory system.',o:['The heart pumps blood to the lungs','The blood picks up oxygen in the lungs','The blood returns to the heart','The heart pumps the blood around the body'],why:'Blood collects oxygen in the lungs, then the heart pumps it to the rest of the body.'},
 {d:'B',s:'K',q:'How are nutrients and water transported around the human body?',o:['In the blood','Along the nerves','Through the bones'],why:'Nutrients and water pass into the blood, which carries them to every part of the body.'},
 {d:'B',s:'W',tb:[['Activity','Pulse rate (beats per minute)'],['Resting','80'],['Walking','100'],['Jogging','130'],['Sprinting','160']],q:'What pattern do these results show?',o:['The more energetic the activity, the higher the pulse rate','The more energetic the activity, the lower the pulse rate','Activity makes no difference to pulse rate'],why:'The pulse rate goes up from 80 (resting) to 160 (sprinting).'},
 {d:'B',s:'A',tb:[['Activity','Pulse rate (beats per minute)'],['Resting','80'],['Walking','100'],['Jogging','130'],['Sprinting','160']],q:'Why does the pulse rate increase during exercise?',o:['The muscles need more oxygen, so the heart pumps faster','The heart gets colder','The body needs less blood'],why:'Working muscles need more oxygen and nutrients, so the heart beats faster to deliver them.'},
 {d:'B',s:'A',q:'Which of these can damage the heart and lungs?',o:['Smoking','Walking every day','Eating vegetables'],why:'Smoking harms the heart and lungs. It is an example of how lifestyle affects the body.'},
 {d:'B',s:'A',q:'Which of these is part of a healthy lifestyle?',o:['A balanced diet, regular exercise and enough sleep','Eating only sweets','Sleeping for two hours a night'],why:'Diet, exercise and sleep all affect how well the body works.'},
 {d:'B',s:'K',q:'What do fossils tell us about living things?',o:['Living things have changed over millions of years','Living things never change','All animals alive today lived millions of years ago'],why:'Fossils provide evidence that living things have changed over time.'},
 {d:'B',s:'K',q:'Mary Anning is famous for…',o:['finding important fossils','discovering electricity','studying chimpanzees'],why:'Mary Anning found fossils of sea reptiles on the cliffs at Lyme Regis.'},
 {d:'B',s:'K',q:'Why are offspring not identical to their parents?',o:['They inherit a mixture of characteristics from both parents','They choose how they look','They eat different food'],why:'Living things produce offspring of the same kind, but offspring vary.'},
 {d:'B',s:'K',q:'What is an adaptation?',o:['A feature that helps a living thing survive in its environment','A type of fossil','A change in the weather'],why:'Adaptations help animals and plants survive in their habitats.'},
 {d:'B',s:'A',v:'i:desert',q:'How is a camel adapted to life in the desert?',o:['Wide feet stop it sinking into the sand','Webbed feet help it swim','Thick white fur keeps it warm'],why:'A camel’s wide feet spread its weight over the soft sand.'},
 {d:'B',s:'A',v:'i:arctic',q:'How is a polar bear adapted to the Arctic?',o:['Thick fur and a layer of fat keep it warm','Large ears help it lose heat','Thin skin keeps it cool'],why:'Fur and fat insulate the polar bear from the freezing cold.'},
 {d:'B',s:'K',q:'On which islands did Charles Darwin study finches with different beaks?',o:['The Galápagos Islands','The British Isles','The Canary Islands'],why:'Darwin’s observations on the Galápagos helped him develop the theory of evolution.'},
 {d:'B',s:'A',q:'Finches with thick, strong beaks lived on an island with lots of hard seeds. Why did they survive well there?',o:['Their beaks were adapted to crack hard seeds','Their beaks were good for catching fish','Their beaks helped them swim'],why:'The finches best suited to their environment survived and passed on their characteristics.'},
 {d:'B',s:'K',q:'What is natural selection?',o:['Living things best suited to their environment survive and pass on their characteristics','Farmers choosing which animals to keep','Animals choosing where to live'],why:'Over many generations, natural selection leads to evolution.'},
 {d:'B',s:'A',t:'two',q:'Which TWO characteristics are inherited from parents?',o:['Natural eye colour','Natural hair colour','A scar on the knee','Being able to ride a bike'],why:'Eye and hair colour are inherited. A scar and riding a bike happen during a person’s life.'},
 {d:'B',s:'K',q:'What type of animal is a shark, and how does it breathe?',o:['A fish; it breathes through gills','A mammal; it breathes with lungs','A reptile; it breathes through its skin'],why:'Sharks are fish. They take oxygen from the water through their gills.'},
 {d:'C',s:'K',q:'Which change is irreversible?',o:['Burning wood','Melting butter','Freezing water'],why:'Burning makes new materials (ash and smoke), so it cannot be reversed.'},
 {d:'C',s:'A',q:'How would you separate sand from water?',o:['Filtering','Using a magnet','Dissolving'],why:'The filter paper lets the water through and traps the sand.'},
 {d:'C',s:'K',q:'Which material is the best electrical conductor?',o:['Copper','Rubber','Wood'],why:'Copper is a metal and conducts electricity well, so it is used in wires.'},
 {d:'C',s:'K',q:'Which state of matter can flow and takes the shape of its container, but keeps the same volume?',o:['Liquid','Solid','Gas'],why:'Liquids flow and take the shape of their container. Gases spread out to fill it.'},
 {d:'P',s:'K',q:'How does light travel?',o:['In straight lines','In circles','Around corners'],why:'Light travels in straight lines. That is why you cannot see around corners.'},
 {d:'P',s:'K',q:'How do we see objects that are not light sources?',o:['Light reflects off the object into our eyes','Our eyes send out light','The object makes a sound'],why:'Objects are seen because they give out or reflect light into the eye.'},
 {d:'P',s:'K',v:'reflect',q:'What does a mirror do to light?',o:['It reflects it','It absorbs all of it','It makes its own light'],why:'Smooth, shiny surfaces like mirrors reflect light.'},
 {d:'P',s:'A',q:'Why does a shadow have the same shape as the object that casts it?',o:['Light travels in straight lines, and the object blocks it','The shadow copies the object','Shadows are made of dark light'],why:'Light that passes the edges travels straight on, so the shadow matches the object’s outline.'},
 {d:'P',s:'A',q:'How does a periscope let you see over a wall?',o:['Two mirrors reflect light into your eye','Light passes through the wall','It makes its own light'],why:'Light reflects off the top mirror, down to the bottom mirror and into your eye.'},
 {d:'P',s:'K',q:'Which material would make the darkest shadow?',o:['Wood (opaque)','Tracing paper (translucent)','Clear glass (transparent)'],why:'Opaque materials block all light, so they make the darkest shadows.'},
 {d:'P',s:'W',tb:[['Distance from torch to object','Height of shadow'],['10 cm','30 cm'],['20 cm','20 cm'],['30 cm','15 cm']],q:'What pattern do these results show?',o:['The closer the object is to the torch, the bigger the shadow','The closer the object is to the torch, the smaller the shadow','Distance makes no difference'],why:'At 10 cm the shadow was 30 cm. At 30 cm it was only 15 cm.'},
 {d:'P',s:'A',q:'A pencil in a glass of water looks bent where it enters the water. Why?',o:['Light changes direction as it passes between water and air','The water bends the pencil','The glass is a mirror'],why:'Light changes direction when it passes from water into air. The pencil is really straight.'},
 {d:'P',s:'K',q:'Which of these is NOT a light source?',o:['The Moon','The Sun','A candle flame'],why:'The Moon does not make its own light. It reflects light from the Sun.'},
 {d:'P',s:'K',v:'symbol:cell',q:'What does this circuit symbol represent?',o:['A cell','A lamp','A switch'],why:'A long line and a short line is the symbol for a cell.'},
 {d:'P',s:'K',v:'symbol:bulb',q:'What does this circuit symbol represent?',o:['A lamp (bulb)','A buzzer','A motor'],why:'A circle with a cross is the symbol for a lamp.'},
 {d:'P',s:'K',v:'symbol:switchopen',q:'What does this circuit symbol represent?',o:['An open switch','A closed switch','A wire'],why:'The gap shows that the switch is open, so no electricity can flow.'},
 {d:'P',s:'A',q:'Another cell is added to a circuit with one lamp. What happens to the lamp?',o:['It gets brighter','It gets dimmer','It goes out'],why:'More cells give a higher voltage, which makes the lamp brighter.'},
 {d:'P',s:'A',q:'A second lamp is added in series to a circuit with one cell. What happens?',o:['Both lamps are dimmer than one lamp on its own','Both lamps are brighter','Only one lamp lights'],why:'The lamps share the voltage from the cell, so each one is dimmer.'},
 {d:'P',s:'A',q:'The voltage in a circuit with a buzzer is increased. What happens to the buzzer?',o:['It gets louder','It gets quieter','It stops'],why:'Increasing the voltage makes a buzzer louder.'},
 {d:'P',s:'K',q:'What is voltage measured in?',o:['Volts (V)','Newtons (N)','Metres (m)'],why:'Voltage is measured in volts. A typical AA cell is 1.5 V.'},
 {d:'P',s:'W',tb:[['Number of cells','Brightness of the lamp'],['1','Dim'],['2','Bright'],['3','Very bright']],q:'Which conclusion do these results support?',o:['The more cells (the higher the voltage), the brighter the lamp','The more cells, the dimmer the lamp','The number of cells makes no difference'],why:'As the number of cells goes up, the lamp gets brighter.'},
 {d:'P',s:'A',v:'symcircuit:open',q:'Look at the circuit diagram. Will the lamp light?',o:['No, because the switch is open','Yes, because there is a cell','Yes, but it will be very dim'],why:'An open switch makes a gap in the circuit, so no electricity can flow.'},
 {d:'B',s:'W',q:'Children want to find out if exercise changes pulse rate. Which question could they investigate?',o:['How does the length of time spent skipping affect pulse rate?','What is your favourite sport?','Which colour T-shirt is best?'],why:'A good scientific question names what you will change and what you will measure.'},
 {d:'P',s:'W',q:'Zara tests how the number of cells affects a lamp’s brightness. Which variable must she keep the same?',o:['The type of lamp','The number of cells','The brightness of the lamp'],why:'She changes the number of cells and observes the brightness. Everything else, like the lamp, must stay the same.'},
 {d:'P',s:'W',q:'Sam measured the same shadow three times and got 20 cm, 21 cm and 35 cm. What should he do?',o:['Repeat the measurement, because 35 cm does not fit the pattern','Use only the 35 cm result','Stop the investigation'],why:'A result that does not fit the pattern may be a mistake. Repeating it checks whether it is reliable.'}
]};

/* ---------------- Form B: a second practice test for every grade ---------------- */
