window.SQ_GLB.kg2 = {qs:[
 {d:'B',s:'K',v:'plant:leaf',q:'What is the name of the part of the plant the arrow is pointing to?',o:['Leaf','Petal','Root'],why:'Leaves are usually green and flat. They use sunlight to make food for the plant.'},
 {d:'B',s:'K',v:'tree:branch',q:'What is the name of the part of the tree the arrow is pointing to?',o:['Branch','Trunk','Root'],why:'Branches grow out from the trunk and hold the leaves.'},
 {d:'B',s:'K',v:'i:pine',q:'A pine tree keeps its needles all year round. Which word describes it?',o:['Evergreen','Deciduous','Wild flower'],why:'Evergreen trees keep their leaves all year.'},
 {d:'B',s:'A',q:'Which of these is most likely to be a garden plant?',o:['A rose planted in a flower bed','A dandelion between paving stones','Moss on a wall'],why:'Garden plants are chosen and planted by people.'},
 {d:'B',s:'K',q:'Which part of a plant holds it up?',o:['The stem','The petals','The roots'],why:'The stem holds the plant up, like a strong back.'},
 {d:'B',s:'K',v:'i:trout',q:'Which group of animals does a trout belong to?',o:['Fish','Birds','Mammals'],why:'A trout is a fish. It has fins and gills and lives in water.'},
 {d:'B',s:'K',t:'two',q:'Which TWO animals are birds?',o:['A hen','A parrot','A bat','A butterfly'],why:'Birds have feathers, wings and a beak. A bat is a mammal and a butterfly is an insect.'},
 {d:'B',s:'A',v:'i:lion',q:'A lion eats other animals. What is a lion?',o:['A carnivore','A herbivore','An omnivore'],why:'A carnivore eats other animals.'},
 {d:'B',s:'A',v:'i:bear',q:'A bear eats berries, fish and honey. What is a bear?',o:['An omnivore','A herbivore','A carnivore'],why:'An omnivore eats both plants and animals.'},
 {d:'B',s:'K',v:'i:nose',q:'Which sense do we use our nose for?',o:['Smell','Hearing','Sight'],why:'We smell with our nose.'},
 {d:'B',s:'K',v:'body:knee',q:'Which part of the body is the arrow pointing to?',o:['Knee','Elbow','Neck'],why:'The knee is the joint in the middle of your leg.'},
 {d:'B',s:'K',v:'i:tongue',q:'Which part of the body do we use to taste?',o:['The tongue','The ear','The elbow'],why:'We taste with our tongue.'},
 {d:'C',s:'K',v:'i:window',q:'Which material is this window made from?',o:['Glass','Wood','Fabric'],why:'Windows are made of glass because it is transparent.'},
 {d:'C',s:'K',v:'i:sock',q:'Which material is this sock made from?',o:['Wool','Metal','Glass'],why:'This sock is made of wool, which is soft and warm.'},
 {d:'C',s:'A',q:'Which material would be best for making a teapot?',o:['Pottery','Chocolate','Paper'],why:'Pottery is hard and waterproof, and it does not melt with hot water.'},
 {d:'C',s:'K',t:'two',q:'Which TWO materials are hard?',o:['Rock','Metal','Cotton wool','Sponge'],why:'Rock and metal are hard. Cotton wool and sponge are soft.'},
 {d:'C',s:'W',tb:[['Object','Does it bend?'],['Paper','Yes'],['Card','Yes'],['Wooden ruler','No'],['Pipe cleaner','Yes']],q:'Children tested which objects bend. Which object did NOT bend?',o:['The wooden ruler','The paper','The pipe cleaner'],why:'The table shows “No” for the wooden ruler. Wood is stiff.'},
 {d:'P',s:'K',v:'season:autumn',q:'Which season does this picture show?',o:['Autumn','Winter','Spring'],why:'In autumn, the leaves turn orange and brown and fall from the trees.'},
 {d:'P',s:'K',q:'In which season is the weather usually coldest in the UK?',o:['Winter','Summer','Spring'],why:'Winter is the coldest season, with the shortest days.'},
 {d:'P',s:'W',v:'bars:Winter=5,Spring=12,Summer=21,Autumn=13',q:'The chart shows the average temperature in each season in °C. Which season is the warmest?',o:['Summer','Winter','Autumn'],why:'The summer bar is the tallest: 21 °C.'}
]};

window.SQ_GLB.g1 = {qs:[
 {d:'B',s:'K',q:'Which of these is alive?',o:['A tree','A rock','A plastic bottle'],why:'A tree is alive. It grows, needs water and makes new seeds.'},
 {d:'B',s:'K',q:'A wooden chair is made from wood. What was the wood before?',o:['Part of a living tree','Something that was never alive','A rock'],why:'Wood comes from trees, so it was once alive.'},
 {d:'B',s:'K',v:'scene:pond',q:'Which habitat is this?',o:['A pond','A desert','The Arctic'],why:'A pond has fresh water, reeds and water plants.'},
 {d:'B',s:'A',v:'i:desert',q:'How is a camel suited to life in the desert?',o:['It can go a long time without drinking water','It has webbed feet for swimming','It has gills to breathe underwater'],why:'Deserts are very dry. Camels can survive for a long time without water.'},
 {d:'B',s:'K',v:'scene:rockpool',q:'Which animal lives in a habitat like this?',o:['A crab','A squirrel','A camel'],why:'Crabs live in rock pools by the sea.'},
 {d:'B',s:'A',q:'Why do woodlice live under logs?',o:['It is dark and damp, and there is food','It is hot and dry','There is lots of sunlight'],why:'Woodlice need damp, dark places. A log gives them shelter and rotting wood to eat.'},
 {d:'B',s:'K',v:'chain:leaf,caterpillar,kiki',q:'What is at the start of this food chain?',o:['A plant','A bird','A caterpillar'],why:'Food chains start with a plant.'},
 {d:'B',s:'A',v:'chain:leaf,caterpillar,kiki',q:'In this food chain, what does the bird eat?',o:['The caterpillar','The leaf','Nothing'],why:'The arrow points from the caterpillar to the bird, so the bird eats the caterpillar.'},
 {d:'B',s:'K',v:'i:bulb',q:'What will grow from this bulb?',o:['A flowering plant, such as a tulip','A light','A rock'],why:'Bulbs, like seeds, grow into new plants.'},
 {d:'B',s:'W',v:'i:cressdry',q:'This cress was not given any water. What does this show?',o:['Plants need water to stay healthy','Plants grow best with no water','Cress does not need light'],why:'Without water, the cress dried up and died.'},
 {d:'B',s:'W',tb:[['Cress','Light?','Water?','What happened'],['A','Yes','Yes','Green and healthy'],['B','No','Yes','Pale and yellow'],['C','Yes','No','Dried up']],q:'Which cress had everything it needed to grow well?',o:['A','B','C'],why:'Cress A had both light and water, and it grew green and healthy.'},
 {d:'B',s:'W',tb:[['Cress','Light?','Water?','What happened'],['A','Yes','Yes','Green and healthy'],['B','No','Yes','Pale and yellow'],['C','Yes','No','Dried up']],q:'Which conclusion do the results support?',o:['Plants need both light and water to grow well','Plants only need light','Plants only need water'],why:'Cress B had no light and Cress C had no water. Both did badly.'},
 {d:'B',s:'K',t:'order',q:'Put the life cycle of a chicken in the correct order.',o:['An egg is laid','A chick hatches','The chick grows','It becomes an adult hen'],why:'Animals, including chickens, have offspring which grow into adults.'},
 {d:'B',s:'K',q:'What are the offspring of a cow called?',o:['Calves','Lambs','Puppies'],why:'A baby cow is a calf.'},
 {d:'B',s:'A',v:'i:tadpole',q:'What will a tadpole grow into?',o:['A frog','A fish','A bird'],why:'Tadpoles grow legs, lose their tails and become frogs.'},
 {d:'B',s:'K',t:'two',q:'Which TWO things do humans need to survive?',o:['Air','Water','A bicycle','Sweets'],why:'Humans need water, food and air to survive.'},
 {d:'B',s:'A',v:'i:run',q:'When you run, what happens to your heartbeat?',o:['It gets faster','It stops','It gets slower'],why:'Your heart beats faster to get more oxygen to your muscles.'},
 {d:'B',s:'A',v:'i:toothbrush',q:'Why should you brush your teeth twice a day?',o:['To remove germs and keep teeth healthy','To make your teeth grow longer','To change their colour'],why:'Good hygiene keeps teeth and gums healthy.'},
 {d:'B',s:'A',q:'Which meal is the most balanced?',o:['Fish with rice and vegetables','A plate of cake','A bag of crisps'],why:'A balanced meal has different types of food in the right amounts.'},
 {d:'C',s:'A',v:'i:trainer',q:'Why do trainers have rubber soles?',o:['Rubber grips the ground so you do not slip','Rubber is transparent','Rubber is magnetic'],why:'Rubber is bendy and grips well, so it is suitable for shoe soles.'},
 {d:'C',s:'K',q:'You pull an elastic band so it gets longer. What are you doing?',o:['Stretching it','Squashing it','Twisting it'],why:'Stretching means pulling something to make it longer.'},
 {d:'C',s:'K',q:'You turn the lid of a jar to open it. Which action is this?',o:['Twisting','Squashing','Stretching'],why:'Turning something round is twisting.'},
 {d:'C',s:'K',t:'two',q:'Which TWO objects are made from metal?',o:['A key','A steel spoon','A cork','A woolly sock'],why:'Keys and steel spoons are metal. Cork comes from trees and wool comes from sheep.'},
 {d:'C',s:'A',q:'Which material would be a bad choice for a chair?',o:['Paper, because it is not strong','Wood, because it is strong','Metal, because it is strong'],why:'A chair must be strong enough to hold a person. Paper is too weak.'},
 {d:'C',s:'A',v:'i:brick',q:'Why are many houses built from bricks?',o:['Bricks are hard, strong and last a long time','Bricks are soft and bendy','Bricks are transparent'],why:'Bricks are strong and hard, so they are suitable for building walls.'},
 {d:'C',s:'A',q:'Which material is the most suitable for a window?',o:['Glass, because it is transparent','Wood, because it is strong','Fabric, because it is soft'],why:'Windows must let light through, so they are made of transparent glass.'},
 {d:'C',s:'W',tb:[['Material','Water soaked up (ml)'],['Paper towel','20'],['Cotton cloth','15'],['Plastic sheet','0']],q:'Which material would be best for wiping up a spill?',o:['Paper towel','Cotton cloth','Plastic sheet'],why:'The paper towel soaked up the most water (20 ml).'},
 {d:'C',s:'W',tb:[['Material','Water soaked up (ml)'],['Paper towel','20'],['Cotton cloth','15'],['Plastic sheet','0']],q:'Which material is waterproof?',o:['Plastic sheet','Paper towel','Cotton cloth'],why:'The plastic sheet soaked up no water at all, so it is waterproof.'},
 {d:'C',s:'K',q:'John Dunlop is famous for inventing…',o:['air-filled rubber tyres','the light bulb','glass'],why:'John Dunlop made the first practical air-filled rubber tyre for bicycles.'},
 {d:'C',s:'A',q:'Why is a cardboard box not good for storing things outside in the rain?',o:['Cardboard soaks up water and goes soft','Cardboard is magnetic','Cardboard is too heavy'],why:'Cardboard is not waterproof.'}
]};

